extension CloudWatchOmniClientTypes {

    /// A telemetry field available for use in query expressions.
    public struct Field: Swift.Sendable {
        /// Child fields nested under this field.
        public var children: [CloudWatchOmniClientTypes.Field]?
        /// The name of the field. Field names are case-sensitive and must be used exactly as returned when referencing them in query expressions.
        /// This member is required.
        public var name: Swift.String?

        public init(
            children: [CloudWatchOmniClientTypes.Field]? = nil,
            name: Swift.String? = nil
        ) {
            self.children = children
            self.name = name
        }
    }
}

public struct ListTelemetryFieldsOutput: Swift.Sendable {
    /// The list of fields available for queries.
    /// This member is required.
    public var fields: [CloudWatchOmniClientTypes.Field]?
    /// A token to retrieve the next page of results, or null if there are no more results.
    public var nextToken: Swift.String?

    public init(
        fields: [CloudWatchOmniClientTypes.Field]? = nil,
        nextToken: Swift.String? = nil
    ) {
        self.fields = fields
        self.nextToken = nextToken
    }
}

public enum CloudWatchOmniClientTypes {}
